contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);
        require(putAmount > 0);

        // Setup: make the caller have some balance and set a lock time.
        c.Put{value: putAmount}(lockTime);

        // Ensure the sender's balance is at least the collect amount, if possible.
        // We do not require it, because the general rule must hold for all inputs.
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        // General rule: Collect succeeds iff all three preconditions hold:
        // 1. The account's balance is at least MinSum
        // 2. The account's balance is at least the requested amount
        // 3. The account's unlock time has passed
        bool shouldSucceed = (beforeBalance >= c.MinSum()) &&
                             (beforeBalance >= collectAmount) &&
                             (block.timestamp > beforeUnlockTime);

        assert(reverted == !shouldSucceed);
    }

    receive() external payable {}
}

